'use server';

import {
  generateInitialEstimate,
} from '@/ai/flows/generate-initial-estimate-from-prompt';
import { z } from 'zod';
import type { InitialEstimateInput, InitialEstimateOutput } from '@/ai/schemas/initial-estimate';
import { extractEntities } from '@/ai/flows/get-next-step-flow';
import type { NextStepInput, NextStepOutput } from '@/ai/schemas/next-step';
import { pingAI } from '@/ai/flows/ping-flow';

const formSchema = z.object({
  squareFootage: z.coerce.number().positive(),
  planType: z.enum(['Open Plan', 'Mixed Use']),
  privateOffices: z.coerce.number().int().nonnegative(),
  ceilingType: z.enum(['Standard', 'Open']),
  ceilingHeight: z.coerce.number().positive(),
});


export async function createEstimate(
  input: z.infer<typeof formSchema>
): Promise<InitialEstimateOutput> {
  const validatedInput: InitialEstimateInput = formSchema.parse(input);

  try {
    const output = await generateInitialEstimate(validatedInput);
    return output;
  } catch (error) {
    console.error('Error generating initial estimate:', error);
    throw new Error('Failed to generate estimate from AI flow.');
  }
}


export async function getConversationalResponse(
  history: NextStepInput['history'],
  collectedData: NextStepInput['collectedData']
): Promise<NextStepOutput> {
  const dataRequirements: {
    key: keyof InitialEstimateInput;
    question: string;
  }[] = [
    {
      key: 'squareFootage',
      question: "What's the total square footage of the project area?",
    },
    {
      key: 'planType',
      question:
        "What type of floor plan are you considering? ('Open Plan' or 'Mixed Use')",
    },
    { key: 'privateOffices', question: 'How many private offices do you need?' },
    {
      key: 'ceilingType',
      question: "What about the ceiling type? 'Standard' or 'Open'?",
    },
    { key: 'ceilingHeight', question: 'And what is the ceiling height in feet?' },
  ];

  const findNextQuestion = (data: Partial<InitialEstimateInput>) => {
    for (const req of dataRequirements) {
      const value = data[req.key];
      if (value === undefined || value === null || value === '') {
        return req.question;
      }
    }
    return null;
  };

  try {
    const lastUserMessage = history[history.length - 1]?.content;
    if (!lastUserMessage) {
      return {
        response: "I'm sorry, I didn't get that. Could you please repeat?",
        updatedData: collectedData,
        isComplete: false,
      };
    }

    const extractedData = await extractEntities(lastUserMessage);
    const updatedData = { ...collectedData, ...extractedData };

    const nextQuestion = findNextQuestion(updatedData);

    if (nextQuestion === null) {
      // All data collected
      return {
        response: 'Thanks! I have everything I need to generate your estimate.',
        updatedData,
        isComplete: true,
      };
    }

    const previousQuestion = findNextQuestion(collectedData);

    let response = nextQuestion;
    // If we didn't get any new info and the question is the same, user was off-topic.
    if (Object.keys(extractedData).length === 0 && previousQuestion === nextQuestion) {
      response = `I'm sorry, I didn't quite get that. ${previousQuestion}`;
    }

    return {
      response: response,
      updatedData: updatedData,
      isComplete: false,
    };
  } catch (error) {
    console.error('Error getting conversational response:', error);
    throw new Error('Failed to get response from AI flow.');
  }
}

export async function testAIConnection(): Promise<string> {
  try {
    const result = await pingAI();
    return result;
  } catch (error: any) {
    console.error('Error testing AI connection:', error);
    return `Failed to test AI connection: ${error.message}`;
  }
}
